SELECT p.id, p.symbol, p.opened_at, p.entry_price, COUNT(*) AS n, MIN(c.low_price) AS low_30m, MAX(c.high_price) AS high_30m, AVG(c.volume) AS avg_vol FROM paper_position p JOIN candle c ON c.symbol = p.symbol AND c.interval_code = '1m' AND c.closed = 1 AND c.open_time BETWEEN p.opened_at - INTERVAL 31 MINUTE AND p.opened_at - INTERVAL 1 MINUTE WHERE p.id IN (104,101,96,91,82,78) GROUP BY p.id, p.symbol, p.opened_at, p.entry_price ORDER BY p.id